146	  private reload(): void {
147	    const savedConfig = readGlobalConfig()?.cloud || {};
148	    this.config = {
149	      appUrl: savedConfig.appUrl || 'https://www.promptfoo.app',
150	      apiHost: savedConfig.apiHost,
151	      apiKey: savedConfig.apiKey,
152	      sharing: savedConfig.sharing,
153	      currentOrganizationId: savedConfig.currentOrganizationId,
154	      currentTeamId: savedConfig.currentTeamId,
155	      teams: savedConfig.teams,
156	    };
