227	  setCurrentTeamId(teamId: string, organizationId?: string): void {
228	    if (organizationId) {
229	      if (!this.config.teams) {
230	        this.config.teams = {};
231	      }
232	      if (!this.config.teams[organizationId]) {
233	        this.config.teams[organizationId] = {};
234	      }
235	      this.config.teams[organizationId].currentTeamId = teamId;
236	    } else {
237	      this.config.currentTeamId = teamId;
238	    }
239	    this.saveConfig();
240	  }
241	
242	  clearCurrentTeamId(organizationId?: string): void {
243	    if (organizationId) {
244	      if (this.config.teams?.[organizationId]) {
245	        delete this.config.teams[organizationId].currentTeamId;
246	      }
247	    } else {
248	      delete this.config.currentTeamId;
249	    }
250	    this.saveConfig();
251	  }
