87	async function fetchCloudConfig(path: string): Promise<unknown> {
88	  const response = await makeRequest(path, 'GET');
89	  if (!response.ok) {
90	    const errorMessage = typeof response.text === 'function' ? await response.text() : '';
91	    logger.error(
92	      `[Cloud] Failed to fetch config from cloud: ${errorMessage}. HTTP Status: ${response.status} -- ${response.statusText}.`,
93	    );
94	    throw new Error(`Failed to fetch config from cloud: ${response.statusText}`);
95	  }
96	  return response.json();
97	}
