140	function normalizeCloudEvalProvider(provider: unknown): unknown {
141	  if (typeof provider !== 'string') {
142	    return provider;
143	  }
144	  if (provider.startsWith(CLOUD_PROVIDER_PREFIX) || !isUuid(provider)) {
145	    return provider;
146	  }
147	  return `${CLOUD_PROVIDER_PREFIX}${provider}`;
148	}
