import type { Command } from 'commander';

type AccessibleTeam = {
  id: string;
  name: string;
  slug: string;
  organizationId: string;
  createdAt: string;
  updatedAt: string;
};

/**
 * Finds a team within a list by identifier, matching by id first, then
 * case-insensitive display name, then slug (in that priority order).
 */
function findTeamByIdentifier(
  teams: AccessibleTeam[],
  identifier: string,
): AccessibleTeam | undefined {
  return (
    teams.find((t) => t.id === identifier) ||
    teams.find((t) => t.name.toLowerCase() === identifier.toLowerCase()) ||
    teams.find((t) => t.slug === identifier)
  );
}

/** Returns the team with the earliest `createdAt` date. */
function getOldestTeam(teams: AccessibleTeam[]): AccessibleTeam {
  return [...teams].sort(
    (a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime(),
  )[0];
}

/**
 * Selects a team from a set scoped to a single organization and persists the
 * selection. For multiple teams the user is prompted interactively; in
 * non-interactive environments (or when the prompt is cancelled) the oldest
 * team is selected without any additional API call.
 */
async function selectTeamFromSet(teams: AccessibleTeam[], organizationId: string): Promise<void> {
  if (teams.length === 0) {
    return;
  }

  if (teams.length === 1) {
    cloudConfig.setCurrentTeamId(teams[0].id, organizationId);
    logger.info(`Team: ${chalk.cyan(teams[0].name)}`);
    return;
  }

  // Multiple teams available.
  if (isNonInteractive()) {
    // Non-interactive (CI): use the oldest team but warn.
    const oldest = getOldestTeam(teams);
    cloudConfig.setCurrentTeamId(oldest.id, organizationId);
    logger.info(`Team: ${chalk.cyan(oldest.name)}`);
    logger.warn(
      chalk.yellow(`\n⚠️  You have access to ${teams.length} teams. Using '${oldest.name}'.`),
    );
    logger.info(chalk.dim(`   Use --team flag to specify: promptfoo auth login --team <name>`));
    return;
  }

  // Interactive: prompt the user to select.
  logger.info('');
  try {
    const answer = await select({
      message: 'Select a team to use:',
      choices: teams.map((team) => ({
        name: team.name,
        value: team.id,
        description: team.slug,
      })),
    });
    const selectedTeam = teams.find((t) => t.id === answer);
    if (selectedTeam) {
      cloudConfig.setCurrentTeamId(selectedTeam.id, organizationId);
      logger.info(`\nTeam: ${chalk.cyan(selectedTeam.name)}`);
    }
  } catch {
    // User cancelled (Ctrl+C) - use the oldest team.
    const oldest = getOldestTeam(teams);
    cloudConfig.setCurrentTeamId(oldest.id, organizationId);
    logger.info(`\nTeam: ${chalk.cyan(oldest.name)} ${chalk.dim('(default)')}`);
  }
}

