    // No flags: default to the organization from the validation response,
    // unless it has no accessible teams but teams exist elsewhere.
    const defaultOrgTeams = allTeams.filter((t) => t.organizationId === fallbackOrganizationId);
    if (defaultOrgTeams.length === 0 && allTeams.length > 0) {
      const oldest = getOldestTeam(allTeams);
      organizationId = oldest.organizationId;
      teamsInOrg = allTeams.filter((t) => t.organizationId === organizationId);
      cloudConfig.setCurrentOrganization(organizationId);
      cloudConfig.cacheTeams(teamsInOrg, organizationId);
      logger.info(`Organization: ${chalk.cyan(organizationId)}`);
    } else {
      organizationId = fallbackOrganizationId;
      teamsInOrg = defaultOrgTeams;
      cloudConfig.setCurrentOrganization(organizationId);
      cloudConfig.cacheTeams(teamsInOrg, organizationId);
    }
  }

  // If both --org and --team were provided, resolve the team within the org.
  if (org && team) {
    const found = findTeamByIdentifier(teamsInOrg, team);
    if (!found) {
      const availableTeams = teamsInOrg.map((t) => t.name).join(', ');
      throw new Error(
        `Team '${team}' not found in organization '${org}'. Available teams: ${availableTeams}`,
      );
    }
    cloudConfig.setCurrentTeamId(found.id, organizationId);
    logger.info(`Team: ${chalk.cyan(found.name)}`);
    return;
  }

